import{AS_OF,facilities,metrics}from'./data.js';
export const mansfieldSources=[
{name:'FuelNet operational and financial visibility',url:'https://mansfield.energy/solutions/data-management/',finding:'Inventory, critical fill levels, invoices, BOLs, and multi-supplier transaction validation already live in Mansfield’s product offering.'},
{name:'LTL / tank-wagon delivery',url:'https://mansfield.energy/logistics/ltl-fuel/',finding:'Mansfield describes LTL as less-than-truckload or tank-wagon fuel delivery; this differs from conventional palletized LTL.'},
{name:'Emergency response fuel',url:'https://mansfield.energy/solutions/emergency-response-fuel/',finding:'Business continuity depends on reliable supply for generators, vehicles, and facilities during disruption.'},
{name:'DEF logistics and storage',url:'https://mansfield.energy/supply/diesel-exhaust-fluid/',finding:'Mansfield emphasizes demand history, storage sizing, logistics cost, and avoiding DEF run-outs.'},
{name:'DeliveryONE network',url:'https://mansfield.energy/logistics/deliveryone-network/',finding:'Its offering spans tank wagons, mobile fueling, DEF, wholesale fuels, additives, and consolidated reporting.'}
];
/** Scenario math only: not connected to real Mansfield tanks, demand, or deliveries. */
export function continuityScenario(v){
const keys=['inventory','dailyUse','reserve','etaHours','delivery','capacity'];
for(const k of keys)if(!Number.isFinite(v[k])||v[k]<0)throw Error('Enter valid, nonnegative values for every field.');
if(v.dailyUse<=0)throw Error('Daily consumption must be greater than zero.');
if(v.capacity<=0||v.inventory>v.capacity)throw Error('Working capacity must be positive and at least the current usable inventory.');
if(v.reserve>v.inventory)throw Error('Reserve cannot exceed current usable inventory.');
const reserveHours=(v.inventory-v.reserve)/v.dailyUse*24,emptyHours=v.inventory/v.dailyUse*24,buffer=reserveHours-v.etaHours,arrivalInventory=Math.max(0,v.inventory-v.dailyUse*v.etaHours/24),postDelivery=arrivalInventory+v.delivery,overCapacity=Math.max(0,postDelivery-v.capacity);
return {reserveHours,emptyHours,buffer,arrivalInventory,postDelivery,overCapacity,lateToReserve:buffer<0,emptyBeforeArrival:v.etaHours>emptyHours,watch:buffer>=0&&buffer<12};
}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
let scenarioValues=null,scenarioResult=null,scenarioError='';
export function applyScenario(values){scenarioValues=values;try{scenarioResult=continuityScenario(values);scenarioError=''}catch(e){scenarioError=e.message;scenarioResult=null}}
export function resetScenario(){scenarioValues=null;scenarioResult=null;scenarioError=''}
export function sampleScenario(){applyScenario({inventory:1800,dailyUse:900,reserve:300,etaHours:44,delivery:2000,capacity:5000})}
export function renderMansfieldValue({ships,data,finance,icon,link,btn}){
const eligible=ships.filter(s=>s.status!=='Cancelled'),invoiced=eligible.filter(s=>s.charges.invoiced!==null),variance=invoiced.filter(s=>s.charges.invoiced!==s.charges.expected),exposure=variance.reduce((n,s)=>n+Math.max(0,s.charges.invoiced-s.charges.expected),0),missingPod=eligible.filter(s=>s.status==='Delivered'&&!s.documents.POD),reviews=data.siteReviews||[],acc=eligible.filter(s=>s.charges.accessorial>0);
const inputs=[['inventory','Usable inventory','gal'],['dailyUse','Average consumption','gal / day'],['reserve','Planning reserve','gal'],['etaHours','Inbound ETA from now','hours'],['delivery','Planned delivery','gal'],['capacity','Working storage capacity','gal']];
const r=scenarioResult;
return`<div class="mansfield-intro"><div class="mansfield-wordmark">M<span>ANSFIELD</span></div><div><strong>Make freight visibility useful to the business.</strong><p>Connect delivery performance to supply continuity, receiving readiness, and financial control.</p></div><button class="btn" data-action="mansfield-research">Research & rationale ${icon('info')}</button></div><div class="value-kpis"><div><small>Invoice variance to review</small><strong>${finance?money(exposure):'Restricted'}</strong><span>${variance.length} demo load${variance.length===1?'':'s'} · not recovered savings</span></div><div><small>Delivered loads missing POD</small><strong>${missingPod.length}</strong><span>${eligible.filter(s=>s.status==='Delivered').length} completed demo loads examined</span></div><div><small>Published sites awaiting validation</small><strong>${facilities.length}</strong><span>${reviews.length} local review record${reviews.length===1?'':'s'} · no docks verified</span></div><div><small>FuelNet / tank inventory</small><strong class="connection-state">Not connected</strong><span>No live run-out or inventory claims</span></div></div><div class="value-grid"><section class="card"><div class="card-head"><div><h2>Will the delivery arrive before the reserve is reached?</h2><p>A scenario planner for fuel and DEF continuity</p></div>${btn('Load sample','continuity-sample','','sm')}</div><div class="pad"><div class="note page-note">Standalone scenario, not a Mansfield tank or shipment. All inputs are user assumptions. A production watch requires validated inventory, usage, tank/site IDs, and carrier ETAs.</div><form data-form="continuity" class="scenario-form"><div class="scenario-inputs">${inputs.map(([key,label,unit])=>`<label>${label}<span class="input-with-unit"><input type="number" name="${key}" value="${scenarioValues?scenarioValues[key]:''}" min="0" step="any" required inputmode="decimal"><span>${unit}</span></span></label>`).join('')}</div><div class="between"><small>Constant consumption; no intervening receipts.</small><button class="btn primary" type="submit">Compare delivery to reserve</button></div></form>${scenarioError?`<div class="note red" role="alert" style="margin-top:16px">${esc(scenarioError)}</div>`:''}${r?`<div class="continuity-result ${r.lateToReserve?'at-risk':r.watch?'watch':'on-plan'}"><div class="between"><strong>${r.emptyBeforeArrival?'Scenario reaches empty before arrival':r.lateToReserve?'Delivery arrives after the planning reserve is reached':r.watch?'Less than 12 hours of planning buffer':'Delivery arrives before the planning reserve is reached'}</strong></div><div class="scenario-result-grid"><div><small>Until planning reserve</small><strong>${r.reserveHours.toFixed(1)}h</strong></div><div><small>Inbound ETA</small><strong>${scenarioValues.etaHours.toFixed(1)}h</strong></div><div><small>Buffer at delivery</small><strong>${r.buffer.toFixed(1)}h</strong></div></div><p>${r.lateToReserve?'Review an earlier delivery window or validated alternate supply with the responsible operations team.':'Monitor source inventory and carrier updates; this scenario is not a guarantee of continuity.'}</p>${r.overCapacity>0?`<div class="note red">Volume check: planned arrival inventory plus delivery exceeds the entered working capacity by ${Math.round(r.overCapacity).toLocaleString()} gal. Validate capacity and delivery quantity before any operating decision.</div>`:`<small>Modeled inventory after delivery: ${Math.round(r.postDelivery).toLocaleString()} gal / ${scenarioValues.capacity.toLocaleString()} gal entered working capacity.</small>`}<details><summary>Assumptions and calculation</summary><p>Time to reserve = (usable inventory − planning reserve) ÷ daily consumption × 24. Buffer = time to reserve − inbound ETA. The 12-hour watch threshold is a demonstration assumption. Actual tank limits, product compatibility, safety reserve, variable consumption, telemetry freshness, and intervening receipts must be independently validated. No ordering, dispatch, or tank-filling action is authorized here.</p></details></div>`:'<div class="scenario-placeholder">Enter a scenario or load the illustrative sample to compare time to reserve against delivery ETA.</div>'}</div></section><section class="card value-why"><div class="card-head"><h2>Where this adds value for Mansfield</h2></div><div class="pad"><div class="value-reason"><span>${icon('clock')}</span><div><h3>Protect continuity</h3><p>Combine supply urgency from FuelNet with shipment commitments and carrier ETAs, so operations can act before a missed delivery becomes a service interruption.</p></div></div><div class="value-reason"><span>${icon('dollar')}</span><div><h3>Explain the cost</h3><p>Make invoice variance, missing delivery evidence, and recurring accessorials easy to investigate. Track validated recovery separately from estimates.</p></div></div><div class="value-reason"><span>${icon('building')}</span><div><h3>Get the receiving site right</h3><p>Validate physical delivery locations, hours, equipment, contacts, and restrictions before onboarding freight. An office or mailing address is not a receiving dock.</p></div></div><div class="note lime">FuelNet already covers much of the fuel-management picture. The proposed BHD contribution is the freight execution and exception layer, using agreed data feeds.</div></div></section></div><div class="section-head"><div><h2>Freight charge & document review</h2><p>Current filtered demo records · investigate first, then validate any recovery</p></div>${link('View all insights →','nav','Insights')}</div><section class="card table-wrap"><table><thead><tr><th>Shipment</th><th>Reason</th><th>Financial context</th><th>Next step</th></tr></thead><tbody>${variance.map(s=>`<tr><td>${link(s.id,'shipment',s.id)}</td><td>Expected vs. invoiced discrepancy</td><td>${finance?`${money(s.charges.expected)} expected → ${money(s.charges.invoiced)} invoiced`:'Finance access required'}</td><td>${link('Open billing review','exception',data.exceptions.find(e=>e.loadId===s.id&&e.type==='Billing discrepancy')?.id||'')}</td></tr>`).join('')}${missingPod.map(s=>`<tr><td>${link(s.id,'shipment',s.id)}</td><td>Delivered, POD unavailable</td><td>Recovery not quantified</td><td>${link('Inspect documents','shipment',s.id)}</td></tr>`).join('')}${!variance.length&&!missingPod.length?'<tr><td colspan="4">No charge or POD review candidates in the selected records.</td></tr>':''}</tbody></table></section><div class="note" style="margin-top:12px">${acc.length} selected demo loads include accessorials. Receiving-site validation can help explain repeated fees, but a fee is not automatically invalid or avoidable. ${link('Review accessorial opportunity','opportunity','OP-102')}</div><div class="section-head"><div><h2>Receiving-site readiness register</h2><p>All 11 public directory entries need operational validation before routing real freight.</p></div>${link('Source discrepancies','location-sources')}</div><div class="card table-wrap"><table><thead><tr><th>Published location</th><th>Directory quality</th><th>Local review</th><th>Action</th></tr></thead><tbody>${facilities.map(f=>{const rev=reviews.find(r=>r.facilityId===f.id);return`<tr><td>${link(f.name+', '+f.state,'facility',f.id)}<small>${esc(f.type)}</small></td><td>${esc(f.quality)}</td><td>${rev?esc(rev.use)+' · '+esc(rev.owner):'Not reviewed'}<small>${rev?'Local annotation only; not independently verified':'Physical delivery location and hours unconfirmed'}</small></td><td>${btn(rev?'Edit local review':'Start local review','site-review',f.id,'sm')}</td></tr>`}).join('')}</tbody></table></div><div class="value-grid" style="margin-top:18px"><section class="card pad"><h2>Define the shipment program before launch</h2><p class="small muted" style="margin:10px 0">Mansfield’s LTL offering includes tank-wagon fuel. The present 176-load dataset models conventional palletized freight and is entirely synthetic.</p><div class="program-comparison"><div><strong>Palletized / equipment freight</strong><p>Pallets, weight, dimensions, class, handling, delivery appointment, BOL and POD.</p></div><div><strong>Fuel / DEF delivery program</strong><p>Product, gallons, tank/site ID, working capacity, inventory timestamp, consumption, compartment/handling requirements, metered delivery evidence, approved carrier capabilities, and fuel-specific pricing.</p></div></div><div class="note amber">No real facility is designated as a tank, warehouse, or operating delivery point based on the public office directory alone.</div></section><section class="card pad"><h2>Practical pilot sequence</h2><ol class="checklist"><li>Confirm the shipment program and operating-site master with Mansfield.</li><li>Launch Sunnybrook shipment visibility, original commitments, PODs, and owned exception workflows.</li><li>Validate invoice discrepancies and receiving-related accessorials.</li><li>Add agreed FuelNet inventory/site feeds if supply continuity is in scope; no supported endpoint has been verified.</li><li>Measure on-time deliveries, time to resolution, validated avoided fees, and actual recovery. Set targets with Mansfield after a baseline.</li></ol>${btn('Read the research','mansfield-research','','primary')}</section></div>`;
}
